steps.code:
phone_token = phone_login['access_token']
coworkers = []
roommates = []
for relationship in ['coworker', 'roommate']:
    page_index = 0
    while True:
        result = apis.phone.search_contacts(access_token=phone_token, relationship=relationship, page_index=page_index, page_limit=20)
        # result is list of contacts
        if not result:
            break
        if relationship == 'coworker':
            coworkers.extend(result)
        else:
            roommates.extend(result)
        if len(result) < 20:
            break
        page_index += 1
print("Coworkers:", coworkers)
print("Roommates:", roommates)

